def cstring(blob, offset): return blob[offset:blob.index(0, offset)].decode("ascii")

def fix(path):
    data=bytearray(path.read_bytes())
    header=list(struct.unpack_from(">16sHHIIIIIHHHHHH",data,0))
    sections=[list(struct.unpack_from(">IIIIIIIIII",data,header[6]+i*header[11])) for i in range(header[12])]
    names_sec=sections[header[13]]; names=data[names_sec[4]:names_sec[4]+names_sec[5]]
